CREATE TABLE IF NOT EXISTS controls(category TEXT,key TEXT,value TEXT,version INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(category,key));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT,category TEXT,key TEXT,old_value TEXT,new_value TEXT,old_version INTEGER,new_version INTEGER,reason TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS actions(key TEXT PRIMARY KEY,module TEXT NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL REFERENCES roles(id),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_buckets(key TEXT NOT NULL,window INTEGER NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(key,window));
CREATE TABLE IF NOT EXISTS content_types(id TEXT PRIMARY KEY,fields TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY,type_id TEXT NOT NULL REFERENCES content_types(id),slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,fields TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','review','scheduled','published','archived')),publish_at INTEGER,author_id INTEGER NOT NULL REFERENCES users(id),version INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES entries(id),snapshot TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media(id INTEGER PRIMARY KEY,name TEXT NOT NULL,mime TEXT NOT NULL,alt TEXT NOT NULL,data BLOB NOT NULL,width INTEGER,height INTEGER,owner_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_references(entry_id INTEGER NOT NULL REFERENCES entries(id),media_id INTEGER NOT NULL REFERENCES media(id),PRIMARY KEY(entry_id,media_id));
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS threads(id INTEGER PRIMARY KEY,category_id INTEGER NOT NULL REFERENCES categories(id),title TEXT NOT NULL,body TEXT NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),locked INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replies(id INTEGER PRIMARY KEY,thread_id INTEGER NOT NULL REFERENCES threads(id),body TEXT NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,room_id INTEGER NOT NULL REFERENCES rooms(id),author_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS presence(room_id INTEGER NOT NULL REFERENCES rooms(id),user_id INTEGER NOT NULL REFERENCES users(id),seen_at INTEGER NOT NULL,PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS api_keys(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,scopes TEXT NOT NULL,expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_age ON messages(created_at);
CREATE INDEX IF NOT EXISTS entries_public ON entries(status,slug);
CREATE INDEX IF NOT EXISTS audit_time ON audit(created_at);
